// Builds the entries of a table's decode or prefill configs with one head dim
// and dtype, and registers their launch functions. Each (table, kernel, head
// dim, dtype) is a translation unit generated by
// cmake/rocm_rdna_singleseq_attn.cmake, so the builds compile in parallel.
#pragma once

#include <iterator>
#include <utility>

#include "rdna_singleseq_attn_tables.h"
#include "rdna_singleseq_decode_attn.cu"
#include "rdna_singleseq_prefill_attn.cu"

namespace rdna_singleseq {

template <class Table, HeadDim kHeadDim, Dtype kDtype, size_t... I>
bool register_decode(std::index_sequence<I...>) {
  (
      [] {
        constexpr DecodeConfig c = Table::decode[I];
        if constexpr (c.head_dim == kHeadDim && c.dtype == kDtype)
          decode_launchers<Table>()[I] = &launch_decode<c>;
      }(),
      ...);
  return true;
}

template <class Table, HeadDim kHeadDim, Dtype kDtype>
bool register_decode() {
  return register_decode<Table, kHeadDim, kDtype>(
      std::make_index_sequence<std::size(Table::decode)>{});
}

template <class Table, HeadDim kHeadDim, Dtype kDtype, size_t... I>
bool register_prefill(std::index_sequence<I...>) {
  (
      [] {
        constexpr PrefillConfig c = Table::prefill[I];
        if constexpr (c.head_dim == kHeadDim && c.dtype == kDtype)
          prefill_launchers<Table>()[I] = &launch_prefill<c>;
      }(),
      ...);
  return true;
}

template <class Table, HeadDim kHeadDim, Dtype kDtype>
bool register_prefill() {
  return register_prefill<Table, kHeadDim, kDtype>(
      std::make_index_sequence<std::size(Table::prefill)>{});
}

}  // namespace rdna_singleseq
